def _canonical_json_sha256(value: Mapping[str, Any]) -> str:
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


RULESET_SHA256 = _canonical_json_sha256(RULESET_SPEC)


class DeltaChatMobileQABriefStateEvaluator(BaseEvaluator):
    """Evaluate human and automatic runs with one identical durable ruleset."""

    RULESET_SHA256 = RULESET_SHA256

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        udid = str(
            params.get("udid")
            or getattr(getattr(controller, "runtime", None), "udid", "")
            or ""
        ).strip()
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="evaluation.params.udid is required; no simulator fallback is allowed",
                metadata={
                    "task_id": TASK_ID,
                    "read_only": True,
                    "ruleset_sha256": RULESET_SHA256,
                },
            )

        binding_checks, observed_parameters = self._binding_checks(params)
        if not all(check["pass"] for check in binding_checks):
            return self._result(
                status=EvalStatus.FAIL,
                message="Mobile Brief evaluator binding is invalid",
                udid=udid,
                checks=binding_checks,
                observed={"parameters": observed_parameters},
            )

        try:
            group_root = _find_shared_app_group_root(
                udid=udid,
                group_id=DELTACHAT_APP_GROUP_ID,
            )
            db_paths = sorted((group_root / "accounts").glob("*/dc.db"))
            if len(db_paths) != 1:
                raise RuntimeError(
                    f"expected exactly one bound Delta Chat account database, found {len(db_paths)}"
                )
            documents = self._resolve_fsnotes_documents(
                udid=udid,
                bundle_id=str(params.get("fsnotes_bundle_id") or FSNOTES_BUNDLE_ID),
            )
            checks, observed = self._evaluate_bound_state(
                db_path=db_paths[0],
                documents=documents,
                minimum_message_id=observed_parameters["minimum_message_id"],
                baseline_max_timestamp=observed_parameters["baseline_max_timestamp"],
                fsnotes_baseline_max_timestamp=observed_parameters[
                    "fsnotes_baseline_max_timestamp"
                ],
                sent_state=observed_parameters["sent_state"],
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read bound iOS app state: {type(exc).__name__}: {exc}",
                metadata={
                    "task_id": TASK_ID,
                    "udid": udid,
                    "read_only": True,
                    "ruleset_sha256": RULESET_SHA256,
                    "exception_type": type(exc).__name__,
                },
            )

        checks[0:0] = binding_checks
        failures = [check for check in checks if not check["pass"]]
        return self._result(
            status=EvalStatus.FAIL if failures else EvalStatus.PASS,
            message=(
                "Delta Chat Mobile Brief notes, sources, exact newlines, shares, and output order all match"
                if not failures
                else "Delta Chat Mobile Brief workflow is missing or mismatches required durable evidence"
            ),
            udid=udid,
            checks=checks,
            observed=observed,
        )

    @classmethod
    def _binding_checks(
        cls,
        params: Mapping[str, Any],
    ) -> tuple[list[dict[str, Any]], dict[str, int]]:
        expected_ruleset = str(params.get("expected_ruleset_sha256") or "").strip()
        observed_parameters = {
            "minimum_message_id": int(params.get("minimum_message_id", DEFAULT_MINIMUM_MESSAGE_ID)),
            "baseline_max_timestamp": int(
                params.get("baseline_max_timestamp", DEFAULT_BASELINE_MAX_TIMESTAMP)
            ),
            "fsnotes_baseline_max_timestamp": int(
                params.get(
                    "fsnotes_baseline_max_timestamp",
                    DEFAULT_FSNOTES_BASELINE_MAX_TIMESTAMP,
                )
            ),
            "sent_state": int(params.get("sent_state", DEFAULT_SENT_STATE)),
        }
        expected_parameters = {
            "minimum_message_id": DEFAULT_MINIMUM_MESSAGE_ID,
            "baseline_max_timestamp": DEFAULT_BASELINE_MAX_TIMESTAMP,
            "fsnotes_baseline_max_timestamp": DEFAULT_FSNOTES_BASELINE_MAX_TIMESTAMP,
            "sent_state": DEFAULT_SENT_STATE,
        }
        return (
            [
                cls._check(
                    "ruleset_binding",
                    expected_ruleset == RULESET_SHA256,
                    steps=[],
                    dimension="binding",
                    expected=RULESET_SHA256,
                    observed=expected_ruleset or None,
                    failure_reason="task YAML is not bound to this evaluator ruleset digest",
                ),
                cls._check(
                    "business_parameter_binding",
                    observed_parameters == expected_parameters,
                    steps=[],
                    dimension="binding",
                    expected=expected_parameters,
                    observed=observed_parameters,
                    failure_reason="task baseline or sent-state parameters differ from the ruleset",
                ),
            ],
            observed_parameters,
        )

    @classmethod
    def _evaluate_bound_state(
        cls,
        *,
        db_path: Path,
        documents: Path,
        minimum_message_id: int,
        baseline_max_timestamp: int,
        fsnotes_baseline_max_timestamp: int,
        sent_state: int,
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        with cls._sqlite_snapshot(db_path) as snapshot:
            connection = sqlite3.connect(f"file:{snapshot.as_posix()}?mode=ro", uri=True)
            connection.row_factory = sqlite3.Row
            try:
                chats = connection.execute(
                    "SELECT id,type,name,param FROM chats ORDER BY id"
                ).fetchall()
                messages = connection.execute(
                    """
                    SELECT m.id,m.chat_id,m.from_id,m.to_id,m.type,m.state,
                           m.timestamp,m.timestamp_sent,COALESCE(m.txt,'') AS txt,
                           COALESCE(m.param,'') AS param,COALESCE(c.name,'') AS chat_name,
                           COALESCE(c.type,0) AS chat_type
                    FROM msgs m
                    LEFT JOIN chats c ON c.id=m.chat_id
                    WHERE m.hidden=0 AND COALESCE(m.deleted,0)=0
                    ORDER BY m.id
                    """
                ).fetchall()
            finally:
                connection.close()

        checks: list[dict[str, Any]] = []
        self_chats = [
            row
            for row in chats
            if int(row["type"] or 0) == 100 and cls._param_value(row["param"], "K") == "1"
        ]
        self_chat_id = int(self_chats[0]["id"]) if len(self_chats) == 1 else None
        checks.append(
            cls._check(
                "bound_saved_messages_chat",
                self_chat_id is not None,
                steps=list(range(1, 80)),
                dimension="final_object",
                expected="exactly one Delta Chat self-chat (type=100, K=1)",
                observed=[{"id": int(row["id"]), "name": str(row["name"])} for row in self_chats],
                failure_reason="Saved Messages self-chat is missing or ambiguous",
            )
        )

        baseline_rows = [row for row in messages if int(row["id"]) < minimum_message_id]
        new_saved_rows = [
            row
            for row in messages
            if self_chat_id is not None
            and int(row["chat_id"]) == self_chat_id
            and int(row["id"]) >= minimum_message_id
        ]
        checks.append(
            cls._check(
                "saved_messages_output_count",
                len(new_saved_rows) == 4,
                steps=[21, 39, 74, 79],
                dimension="final_object",
                expected={"count": 4, "minimum_message_id": minimum_message_id},
                observed={"count": len(new_saved_rows), "ids": [int(row["id"]) for row in new_saved_rows]},
                failure_reason="Saved Messages does not contain exactly the four task outputs",
            )
        )

        first_note_path = documents / FIRST_NOTE_NAME
        second_note_path = documents / SECOND_NOTE_NAME
        first_note_bytes = first_note_path.read_bytes() if first_note_path.is_file() else b""
        second_note_bytes = second_note_path.read_bytes() if second_note_path.is_file() else b""
        first_note_lines = cls._logical_lines(first_note_bytes)
        second_note_lines = cls._logical_lines(second_note_bytes)
        first_note_stat = cls._file_times(first_note_path)
        second_note_stat = cls._file_times(second_note_path)

        new_markdown_paths = [
            path
            for path in documents.glob("*.markdown")
            if path.is_file()
            and max(cls._file_times(path).values()) > fsnotes_baseline_max_timestamp
        ]
        checks.append(
            cls._check(
                "fsnotes_output_count",
                {path.name for path in new_markdown_paths} == {FIRST_NOTE_NAME, SECOND_NOTE_NAME},
                steps=[8, 48],
                dimension="final_object",
                expected=sorted([FIRST_NOTE_NAME, SECOND_NOTE_NAME]),
                observed=sorted(path.name for path in new_markdown_paths),
                failure_reason="FSNotes post-baseline Markdown objects are missing, extra, or misnamed",
            )
        )

        selected_sources: dict[str, dict[str, Any]] = {}
        note_lines_by_key = {"first": first_note_lines, "second": second_note_lines}
        for spec in SOURCE_SPECS:
            note_lines = note_lines_by_key[str(spec["note"])]
            candidates = [
                row
                for row in baseline_rows
                if str(row["chat_name"]) == str(spec["chat"])
                and str(spec["token"]) in str(row["txt"])
                and str(row["txt"]) in note_lines
            ]
            selected = candidates[0] if len(candidates) == 1 else None
            if selected is not None:
                selected_sources[str(spec["key"])] = cls._message_summary(selected)
            checks.append(
                cls._check(
                    f"source_provenance:{spec['key']}",
                    selected is not None,
                    steps=list(spec["steps"]),
                    dimension="source_process",
                    expected={
                        "chat": spec["chat"],
                        "token": spec["token"],
                        "complete_message_as_one_line": True,
                        "destination_note": spec["note"],
                    },
                    observed=[cls._message_summary(row) for row in candidates],
                    failure_reason=(
                        "the designated note does not contain exactly one complete matching baseline "
                        f"message from {spec['chat']}"
                    ),
                )
            )

        expected_first_lines = cls._resolve_line_spec(FIRST_NOTE_LINE_SPEC, selected_sources)
        expected_second_lines = cls._resolve_line_spec(SECOND_NOTE_LINE_SPEC, selected_sources)
        expected_first_bytes = cls._expected_bytes(expected_first_lines)
        expected_second_bytes = cls._expected_bytes(expected_second_lines)

        first_new = (
            first_note_path.is_file()
            and first_note_stat["birthtime"] > fsnotes_baseline_max_timestamp
            and first_note_stat["mtime"] > fsnotes_baseline_max_timestamp
        )
        checks.append(
            cls._check(
                "first_note_object_new",
                first_new,
                steps=[7, 8],
                dimension="final_object",
                expected={
                    "filename": FIRST_NOTE_NAME,
                    "created_after": fsnotes_baseline_max_timestamp,
                },
                observed={"exists": first_note_path.is_file(), **first_note_stat},
                failure_reason="the first unique post-baseline FSNotes object is missing or stale",
            )
        )
        first_exact = expected_first_bytes is not None and first_note_bytes == expected_first_bytes
        checks.append(
            cls._check(
                "first_note_exact_bytes_and_newlines",
                first_exact,
                steps=[7, 8, 9, 10, 12, 13, 14, 15, 16, 28, 29, 30, 32, 33, 34],
                dimension="content_parameter",
                expected={
                    "lines": expected_first_lines,
                    "separator": "exactly one LF between adjacent lines and no trailing LF",
                    "newline_steps": [10, 13, 15, 28, 30, 33],
                    "create_return_step": 8,
                },
                observed={"lines": first_note_lines, "size": len(first_note_bytes)},
                failure_reason="the first note has missing, extra, reordered, or wrongly separated bytes",
            )
        )

        second_new = (
            second_note_path.is_file()
            and second_note_stat["birthtime"] > fsnotes_baseline_max_timestamp
            and second_note_stat["mtime"] > fsnotes_baseline_max_timestamp
        )
        checks.append(
            cls._check(
                "second_note_object_new",
                second_new,
                steps=[47, 48],
                dimension="final_object",
                expected={
                    "filename": SECOND_NOTE_NAME,
                    "created_after": fsnotes_baseline_max_timestamp,
                },
                observed={"exists": second_note_path.is_file(), **second_note_stat},
                failure_reason="the second unique post-baseline FSNotes object is missing or stale",
            )
        )
        second_exact = expected_second_bytes is not None and second_note_bytes == expected_second_bytes
        checks.append(
            cls._check(
                "second_note_exact_bytes_and_newlines",
                second_exact,
                steps=[47, 48, 49, 50, 52, 53, 54, 55, 56, 63, 64, 65, 67, 68, 69],
                dimension="content_parameter",
                expected={
                    "lines": expected_second_lines,
                    "separator": "exactly one LF between adjacent lines and no trailing LF",
                    "newline_steps": [50, 53, 55, 63, 65, 68],
                    "create_return_step": 48,
                },
                observed={"lines": second_note_lines, "size": len(second_note_bytes)},
                failure_reason="the second note has missing, extra, reordered, or wrongly separated bytes",
            )
        )

        source_order_ok = (
            all(str(spec["key"]) in selected_sources for spec in SOURCE_SPECS)
            and not any(
                selected_sources[str(spec["key"])]["text"]
                in note_lines_by_key["second" if spec["note"] == "first" else "first"]
                for spec in SOURCE_SPECS
            )
        )
        checks.append(
            cls._check(
                "source_messages_in_instruction_order",
                source_order_ok,
                steps=[12, 32, 52, 67],
                dimension="source_process",
                expected=[str(spec["chat"]) for spec in SOURCE_SPECS],
                observed={
                    "source_keys": [str(spec["key"]) for spec in SOURCE_SPECS],
                    "selected": selected_sources,
                },
                failure_reason="the four complete sources are missing, assigned to the wrong note, or out of workflow order",
            )
        )

        sync_rows = [
            row
            for row in new_saved_rows
            if int(row["type"]) == 10
            and int(row["state"]) == sent_state
            and str(row["txt"]) == "iOS brief synced"
        ]
        sync_row = sync_rows[0] if len(sync_rows) == 1 else None
        checks.append(
            cls._check(
                "sync_status_message",
                sync_row is not None,
                steps=[19, 20, 21],
                dimension="final_object",
                expected={"exact_text": "iOS brief synced", "state": sent_state},
                observed=[cls._message_summary(row) for row in sync_rows],
                failure_reason="the exact sent first status message is missing or duplicated",
            )
        )

        final_rows = [
            row
            for row in new_saved_rows
            if int(row["type"]) == 10
            and int(row["state"]) == sent_state
            and str(row["txt"]) == "Brief archived\nGate ready"
        ]
        final_row = final_rows[0] if len(final_rows) == 1 else None
        checks.append(
            cls._check(
                "final_archive_message_exact_newline",
                final_row is not None,
                steps=[75, 76, 77, 78, 79],
                dimension="content_parameter",
                expected={
                    "raw_text": "Brief archived\nGate ready",
                    "logical_lines": ["Brief archived", "Gate ready"],
                    "newline_step": 77,
                    "state": sent_state,
                },
                observed=[cls._message_summary(row) for row in final_rows],
                failure_reason="the terminal message is missing, duplicated, unsent, or does not contain exactly one LF",
            )
        )

        first_attachment_rows = cls._attachment_rows(new_saved_rows, FIRST_NOTE_NAME)
        second_attachment_rows = cls._attachment_rows(new_saved_rows, SECOND_NOTE_NAME)
        first_attachment_row = first_attachment_rows[0] if len(first_attachment_rows) == 1 else None
        second_attachment_row = second_attachment_rows[0] if len(second_attachment_rows) == 1 else None
        first_attachment_evidence, first_attachment_bytes = cls._attachment_blob(
            db_path=db_path,
            row=first_attachment_row,
            expected_filename=FIRST_NOTE_NAME,
            sent_state=sent_state,
            baseline_max_timestamp=baseline_max_timestamp,
        )
        second_attachment_evidence, second_attachment_bytes = cls._attachment_blob(
            db_path=db_path,
            row=second_attachment_row,
            expected_filename=SECOND_NOTE_NAME,
            sent_state=sent_state,
            baseline_max_timestamp=baseline_max_timestamp,
        )
        first_attachment_ok = (
            first_attachment_row is not None
            and bool(first_attachment_evidence.get("base_pass"))
            and expected_first_bytes is not None
            and first_attachment_bytes == expected_first_bytes
        )
        checks.append(
            cls._check(
                "first_saved_attachment",
                first_attachment_ok,
                steps=list(range(35, 40)),
                dimension="final_object",
                expected="one sent post-baseline first-note attachment with exact bytes",
                observed=first_attachment_evidence,
                failure_reason="the first Saved Messages attachment is missing, unsafe, stale, unsent, or has wrong bytes",
            )
        )
        second_attachment_ok = (
            second_attachment_row is not None
            and bool(second_attachment_evidence.get("base_pass"))
            and expected_second_bytes is not None
            and second_attachment_bytes == expected_second_bytes
        )
        checks.append(
            cls._check(
                "second_saved_attachment",
                second_attachment_ok,
                steps=list(range(70, 75)),
                dimension="final_object",
                expected="one sent post-baseline second-note attachment with exact bytes",
                observed=second_attachment_evidence,
                failure_reason="the second Saved Messages attachment is missing, unsafe, stale, unsent, or has wrong bytes",
            )
        )

        files_equal = (
            bool(first_note_bytes)
            and bool(second_note_bytes)
            and first_note_bytes == first_attachment_bytes
            and second_note_bytes == second_attachment_bytes
        )
        checks.append(
            cls._check(
                "fsnotes_equals_attachments",
                files_equal,
                steps=[34, 39, 69, 74],
                dimension="source_process",
                expected="each shared attachment is byte-identical to its bound FSNotes object",
                observed={
                    "first_note_sha256": cls._sha256_bytes(first_note_bytes),
                    "first_attachment_sha256": cls._sha256_bytes(first_attachment_bytes),
                    "second_note_sha256": cls._sha256_bytes(second_note_bytes),
                    "second_attachment_sha256": cls._sha256_bytes(second_attachment_bytes),
                },
                failure_reason="an attachment is not the exact corresponding FSNotes file",
            )
        )

        ordered_rows = [sync_row, first_attachment_row, second_attachment_row, final_row]
        ordered_ids = [int(row["id"]) for row in ordered_rows if row is not None]
        ordered_timestamps = [int(row["timestamp"] or 0) for row in ordered_rows if row is not None]
        timestamps_sorted = ordered_timestamps == sorted(ordered_timestamps)
        timestamps_distinct = len(set(ordered_timestamps)) == 4
        business_order_ok = (
            len(ordered_ids) == 4
            and [int(row["id"]) for row in new_saved_rows] == ordered_ids
            and ordered_ids == sorted(ordered_ids)
            and len(set(ordered_ids)) == 4
            and timestamps_sorted
        )
        checks.append(
            cls._check(
                "saved_outputs_business_order",
                business_order_ok,
                steps=[21, 39, 74, 79],
                dimension="source_process",
                expected="exactly status < first attachment < second attachment < final two-line status by distinct message id and non-decreasing timestamp (equal timestamps are a non-blocking diagnostic)",
                observed={"message_ids": ordered_ids, "timestamps": ordered_timestamps, "timestamps_distinct_diagnostic": timestamps_distinct},
                failure_reason="the four Saved Messages outputs are missing, extra, duplicated, or out of order",
            )
        )

        sync_timestamp = cls._row_timestamp(sync_row)
        first_attachment_timestamp = cls._row_timestamp(first_attachment_row)
        second_attachment_timestamp = cls._row_timestamp(second_attachment_row)
        final_timestamp = cls._row_timestamp(final_row)
        cross_app_chronology_diagnostic = (
            first_new
            and second_new
            and first_note_stat["birthtime"] <= second_note_stat["birthtime"]
            and first_note_stat["birthtime"] < sync_timestamp
            and sync_timestamp < first_note_stat["mtime"] < first_attachment_timestamp
            and first_attachment_timestamp < second_note_stat["mtime"] < second_attachment_timestamp
            and second_attachment_timestamp < final_timestamp
        )
        checks.append(
            cls._check(
                "cross_app_creation_and_share_order",
                True,
                steps=[8, 21, 39, 48, 74, 79],
                dimension="diagnostic",
                expected=(
                    "non-blocking diagnostic: first-note birth < sync send < first-note final mtime < "
                    "first share < second-note final mtime < second share < final send; "
                    "content, provenance, and attachment-byte invariants above are authoritative"
                ),
                observed={
                    "first_note": first_note_stat,
                    "sync_timestamp": sync_timestamp or None,
                    "first_attachment_timestamp": first_attachment_timestamp or None,
                    "second_note": second_note_stat,
                    "second_attachment_timestamp": second_attachment_timestamp or None,
                    "final_timestamp": final_timestamp or None,
                    "chronology_satisfied_diagnostic": cross_app_chronology_diagnostic,
                },
                failure_reason="",
            )
        )

        observed = {
            "database_path": str(db_path),
            "fsnotes_documents": str(documents),
            "saved_messages_chat_id": self_chat_id,
            "minimum_message_id": minimum_message_id,
            "baseline_max_timestamp": baseline_max_timestamp,
            "fsnotes_baseline_max_timestamp": fsnotes_baseline_max_timestamp,
            "new_saved_messages": [cls._message_summary(row) for row in new_saved_rows],
            "selected_source_messages": selected_sources,
            "first_note": {
                "path": str(first_note_path),
                "sha256": cls._sha256_bytes(first_note_bytes),
                "logical_lines": first_note_lines,
                **first_note_stat,
            },
            "second_note": {
                "path": str(second_note_path),
                "sha256": cls._sha256_bytes(second_note_bytes),
                "logical_lines": second_note_lines,
                **second_note_stat,
            },
            "attachments": [first_attachment_evidence, second_attachment_evidence],
        }
        return checks, observed

    @classmethod
    def _result(
        cls,
        *,
        status: EvalStatus,
        message: str,
        udid: str,
        checks: list[dict[str, Any]],
        observed: Mapping[str, Any],
    ) -> EvalResult:
        failures = [check for check in checks if not check["pass"]]
        return EvalResult(
            status=status,
            message=message,
            metadata={
                "task_id": TASK_ID,
                "udid": udid,
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "checks": checks,
                "failures": failures,
                "observed": dict(observed),
                "step_coverage": cls._step_coverage(checks),
                "coverage_summary": {
                    "instruction_steps": 79,
                    "mapped_steps": 79,
                    "data_producing_steps": sorted(DATA_PRODUCING_STEPS),
                    "note_create_return_steps": list(NOTE_CREATE_RETURN_STEPS),
                    "newline_steps": list(NEWLINE_STEPS),
                    "newline_check": "exact raw UTF-8 bytes with one LF at every requested durable line break",
                    "final_ui": "not_required_after_terminal_send_submission",
                },
                "verifier_rules": [
                    "Human eval-only and automatic execution use this exact evaluator and RULESET_SHA256.",
                    "Only the bound Delta Chat database, FSNotes files, and Delta attachment blobs are authoritative.",
                    "Each copied source must equal one complete baseline message from its named chat and occupy its instructed note line.",
                    "Every typed value and requested durable Return result is checked by exact raw-byte equality (only the explicit app-managed title prefixes are normalized).",
                    "The four Saved Messages outputs must be the only post-baseline outputs and occur in instructed distinct-id, non-decreasing-timestamp order.",
                    "Each attachment must be byte-identical to the corresponding bound FSNotes file.",
                    "Cross-app creation/edit/share chronology is a non-blocking diagnostic.",
                    "No trajectory, recording, screenshot, Appium session, initializer, or GUI action is used.",
                ],
            },
        )

    @classmethod
    def _step_coverage(cls, checks: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        by_name = {str(check["name"]): check for check in checks}
        coverage: list[dict[str, Any]] = []
        for group in STEP_GROUPS:
            names = list(group["checkpoint_names"])
            group_pass = all(name in by_name and bool(by_name[name].get("pass")) for name in names)
            for step in group["steps"]:
                coverage.append(
                    {
                        "step": step,
                        "role": (
                            "data_producing_or_compound"
                            if step in DATA_PRODUCING_STEPS
                            else "required_navigation"
                        ),
                        "checkpoint_names": names,
                        "mapping_basis": "shared read-only cross-object invariant",
                        "purpose": group["purpose"],
                        "dimensions": {
                            "final_object": "covered",
                            "content_parameter": "covered",
                            "source_process": "covered_by_source_content_and_order_invariants",
                            "final_ui": "not_applicable_after_terminal_send",
                        },
                        "pass": group_pass,
                    }
                )
        return sorted(coverage, key=lambda item: int(item["step"]))

    @staticmethod
    def _check(
        name: str,
        passed: bool,
        *,
        steps: list[int],
        dimension: str,
        expected: Any,
        observed: Any,
        failure_reason: str,
    ) -> dict[str, Any]:
        return {
            "name": name,
            "pass": bool(passed),
            "steps": steps,
            "dimension": dimension,
            "expected": expected,
            "observed": observed,
            "failure_reason": None if passed else failure_reason,
        }

    @staticmethod
    def _attachment_rows(rows: Sequence[sqlite3.Row], filename: str) -> list[sqlite3.Row]:
        return [
            row
            for row in rows
            if int(row["type"]) == 60
            and DeltaChatMobileQABriefStateEvaluator._param_value(row["param"], "v") == filename
        ]

    @classmethod
    def _attachment_blob(
        cls,
        *,
        db_path: Path,
        row: sqlite3.Row | None,
        expected_filename: str,
        sent_state: int,
        baseline_max_timestamp: int,
    ) -> tuple[dict[str, Any], bytes]:
        if row is None:
            return ({"base_pass": False, "filename": expected_filename, "message_id": None}, b"")
        params = cls._parse_params(row["param"])
        filename = params.get("v", "")
        raw_blob = params.get("f", "")
        blob_root = (db_path.parent / "dc.db-blobs").resolve()
        blob_path: Path | None = None
        safe = False
        if raw_blob.startswith("$BLOBDIR/"):
            candidate = (blob_root / raw_blob.removeprefix("$BLOBDIR/")).resolve()
            if candidate.is_relative_to(blob_root):
                blob_path = candidate
                safe = True
        blob_bytes = blob_path.read_bytes() if safe and blob_path and blob_path.is_file() else b""
        try:
            blob_bytes.decode("utf-8-sig")
            utf8_ok = bool(blob_bytes)
        except UnicodeDecodeError:
            utf8_ok = False
        base_pass = (
            filename == expected_filename
            and int(row["state"]) == sent_state
            and int(row["timestamp"] or 0) > baseline_max_timestamp
            and safe
            and bool(blob_bytes)
            and utf8_ok
        )
        return (
            {
                "base_pass": base_pass,
                "message_id": int(row["id"]),
                "filename": filename,
                "state": int(row["state"]),
                "timestamp": int(row["timestamp"] or 0),
                "blob_path": str(blob_path) if blob_path else None,
                "blob_path_safe": safe,
                "size": len(blob_bytes),
                "sha256": cls._sha256_bytes(blob_bytes),
                "logical_lines": cls._logical_lines(blob_bytes),
            },
            blob_bytes,
        )

    @staticmethod
    def _resolve_line_spec(
        spec: Sequence[tuple[str, str]],
        sources: Mapping[str, Mapping[str, Any]],
    ) -> list[str] | None:
        lines: list[str] = []
        for kind, value in spec:
            if kind == "literal":
                lines.append(value)
            elif value in sources:
                lines.append(str(sources[value]["text"]))
            else:
                return None
        return lines

    @staticmethod
    def _expected_bytes(lines: Sequence[str] | None) -> bytes | None:
        if lines is None:
            return None
        return "\n".join(lines).encode("utf-8")

    @staticmethod
    def _logical_lines(payload: bytes) -> list[str]:
        if not payload:
            return []
        try:
            text = payload.decode("utf-8-sig")
        except UnicodeDecodeError:
            return []
        # The creation title is app-managed, not a user-requested body line.
        # Only the two explicit note-title prefixes are normalized (cf. 4_3);
        # every other byte, including wrong content, is compared strictly.
        for title, heading in (
            (FIRST_NOTE_TITLE, "# Mobile brief"),
            (SECOND_NOTE_TITLE, "# Mobile risks"),
        ):
            if text.startswith(title + heading):
                text = text[len(title):]
                break
            if text.startswith(title + "\n" + heading):
                text = text[len(title) + 1:]
                break
        normalized = text.replace("\r\n", "\n").replace("\r", "\n")
        return normalized.split("\n")

    @staticmethod
    def _message_summary(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "id": int(row["id"]),
            "chat_id": int(row["chat_id"]),
            "chat_name": str(row["chat_name"]),
            "from_id": int(row["from_id"]),
            "to_id": int(row["to_id"]),
            "type": int(row["type"]),
            "state": int(row["state"]),
            "timestamp": int(row["timestamp"] or 0),
            "timestamp_sent": int(row["timestamp_sent"] or 0),
            "text": str(row["txt"]),
            "attachment_name": DeltaChatMobileQABriefStateEvaluator._param_value(row["param"], "v"),
        }

    @staticmethod
    def _resolve_fsnotes_documents(*, udid: str, bundle_id: str) -> Path:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "data"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode == 0 and proc.stdout.strip():
            from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
            root = remap_simulator_container_path(proc.stdout.strip(), udid)
        else:
            container = _find_app_data_container_by_metadata(udid=udid, bundle_id=bundle_id)
            if container is None:
                raise RuntimeError(f"FSNotes data-container lookup failed: {proc.stderr.strip()}")
            root = container.resolve()
        documents = (root / "Documents").resolve()
        if not documents.is_dir():
            raise FileNotFoundError(f"FSNotes Documents directory is missing: {documents}")
        return documents

    @staticmethod
    @contextmanager
    def _sqlite_snapshot(db_path: Path) -> Iterator[Path]:
        """Create a consistent host-side copy through a read-only SQLite connection."""

        with tempfile.TemporaryDirectory(prefix="ios-deltachat-mobile-brief-eval-") as temp_dir:
            snapshot = Path(temp_dir) / "dc.db"
            source = sqlite3.connect(f"file:{db_path.as_posix()}?mode=ro", uri=True)
            destination = sqlite3.connect(snapshot)
            try:
                source.backup(destination)
            finally:
                destination.close()
                source.close()
            yield snapshot

    @staticmethod
    def _file_times(path: Path) -> dict[str, float]:
        if not path.is_file():
            return {"birthtime": 0.0, "mtime": 0.0}
        stat = path.stat()
        return {
            "birthtime": float(getattr(stat, "st_birthtime", stat.st_mtime)),
            "mtime": float(stat.st_mtime),
        }

    @staticmethod
    def _row_timestamp(row: sqlite3.Row | None) -> int:
        return int(row["timestamp"] or 0) if row is not None else 0

    @staticmethod
    def _parse_params(raw: Any) -> dict[str, str]:
        values: dict[str, str] = {}
        for line in str(raw or "").splitlines():
            if "=" in line:
                key, value = line.split("=", 1)
                values[key] = value
        return values

    @classmethod
    def _param_value(cls, raw: Any, key: str) -> str:
        return cls._parse_params(raw).get(key, "")

    @staticmethod
    def _sha256_bytes(payload: bytes) -> str | None:
        return hashlib.sha256(payload).hexdigest() if payload else None
